  const deletionStatus = (value: Row): Row => {
    const dependencies: string[] = [];
    const dependency = (code: string, sql: string, params: any[]) => { if (row(context.database.client, sql, params)) dependencies.push(code); };
    dependency("CLASS_HISTORY", "SELECT id FROM student_enrollment_class_history WHERE enrollment_id = ? LIMIT 1", [value.id]);
    dependency("GRADES", "SELECT id FROM student_subject_grades WHERE enrollment_id = ? LIMIT 1", [value.id]);
    dependency("INTERVENTIONS", "SELECT id FROM academic_interventions WHERE enrollment_id = ? LIMIT 1", [value.id]);
    dependency("LIFECYCLE_AUDIT", "SELECT id FROM student_enrollment_lifecycle_audit WHERE enrollment_id = ? LIMIT 1", [value.id]);
    dependency("IMPORT_HISTORY", "SELECT id FROM student_import_applied_actions WHERE entity_type = 'STUDENT_ENROLLMENT' AND entity_id = ? LIMIT 1", [String(value.id)]);
    if (value.student_id !== null) dependency("ATTENDANCE", "SELECT id FROM attendance WHERE student_id = ? LIMIT 1", [value.student_id]);
    const allowed = value.lifecycle_state === "DRAFT" && !value.class_assigned && dependencies.length === 0;
    return { can_hard_delete: allowed, code: allowed ? "HARD_DELETE_ALLOWED" : "ENROLLMENT_HAS_HISTORY", message: allowed ? "Unused draft enrollment may be deleted." : "Enrollment history must be preserved; use an explicit lifecycle action.", dependencies };
  };
